})

export default function (expectation) {
  const erroneousQuote = (expectation === "single") ? "\"" : "'"

  return (root, result) => {
    const validOptions = validateOptions(result, ruleName, {
      actual: expectation,
      possible: [
        "single",
        "double",
      ],
    })
    if (!validOptions) { return }

